    $t$sales_showcase_offer_request$t$, $t$Podaj poprawny termin wydarzenia.$t$, $t$Podaj poprawny termin eventu.$t$,
    $t$save_event_settlement_group$t$, $t$Brak uprawnień do zarządzania rozliczeniem wydarzenia %.$t$, $t$Brak uprawnień do zarządzania rozliczeniem eventu %.$t$,
    $t$save_event_settlement_group$t$, $t$Jedno z wydarzeń należy już do innej grupy rozliczeniowej.$t$, $t$Jeden z eventów należy już do innej grupy rozliczeniowej.$t$,
    $t$save_event_settlement_group$t$, $t$Nie znaleziono wydarzenia %.$t$, $t$Nie znaleziono eventu %.$t$,
