    $t$sync_event_steps$t$, $t$Dane wydarzenia$t$, $t$Dane eventu$t$,
    $t$sync_event_steps$t$, $t$Poza zakresem wydarzenia.$t$, $t$Poza zakresem eventu.$t$,
    $t$sync_event_steps$t$, $t$Wydarzenie anulowane.$t$, $t$Event anulowany.$t$,
    $t$sync_event_steps$t$, $t$Wydarzenie rozliczone.$t$, $t$Event rozliczony.$t$,
    $t$translate_permission_key$t$, $t$Wydarzenia - Przeglądanie$t$, $t$Eventy - Przeglądanie$t$,
    $t$translate_permission_key$t$, $t$Wydarzenia - Zarządzanie$t$, $t$Eventy - Zarządzanie$t$,
    $t$update_accepted_offer_items$t$, $t$Ten sprzęt ma także osobne rezerwacje w wydarzeniu. Uzgodnij ich zakres przed aktualizacją.$t$, $t$Ten sprzęt ma także osobne rezerwacje w evencie. Uzgodnij ich zakres przed aktualizacją.$t$,
    $t$update_accepted_offer_items$t$, $t$Wydarzenie ma inną zaakceptowaną ofertę. Najpierw uporządkuj powiązania.$t$, $t$Event ma inną zaakceptowaną ofertę. Najpierw uporządkuj powiązania.$t$,
    $t$update_event_step$t$, $t$Cofnąć krok może osoba, która go zamknęła, administrator albo osoba z uprawnieniem do zarządzania wydarzeniami.$t$, $t$Cofnąć krok może osoba, która go zamknęła, administrator albo osoba z uprawnieniem do zarządzania eventami.$t$,
    $t$update_event_step$t$, $t$Pominąć krok może administrator albo osoba z uprawnieniem do zarządzania wydarzeniami.$t$, $t$Pominąć krok może administrator albo osoba z uprawnieniem do zarządzania eventami.$t$,
    $t$update_event_step$t$, $t$Ten krok wynika z procesu wydarzenia — cofnij go tam, gdzie został potwierdzony.$t$, $t$Ten krok wynika z procesu eventu — cofnij go tam, gdzie został potwierdzony.$t$,
    $t$update_event_step$t$, $t$Ten krok zamyka się sam, gdy dane w wydarzeniu są uzupełnione — przejdź do zakładki opisanej w kroku.$t$, $t$Ten krok zamyka się sam, gdy dane w evencie są uzupełnione — przejdź do zakładki opisanej w kroku.$t$,
    $t$validate_event_referring_sales_partner$t$, $t$Brak dostępu do marki wydarzenia$t$, $t$Brak dostępu do marki eventu$t$,
    $t$validate_event_referring_sales_partner$t$, $t$Brak uprawnień do przypisania prowizji przy tworzeniu wydarzenia$t$, $t$Brak uprawnień do przypisania prowizji przy tworzeniu eventu$t$,
    $t$validate_event_referring_sales_partner$t$, $t$Brak uprawnień do zmiany sprzedawcy polecającego to wydarzenie$t$, $t$Brak uprawnień do zmiany sprzedawcy polecającego ten event$t$,
    $t$validate_event_rooms$t$, $t$Wybierz różne sale należące do obiektu wydarzenia$t$, $t$Wybierz różne sale należące do obiektu eventu$t$,
    $t$validate_event_vehicle_driver$t$, $t$Kierowca nie ma wszystkich wymaganych kategorii ważnych w dniu wydarzenia.$t$, $t$Kierowca nie ma wszystkich wymaganych kategorii ważnych w dniu eventu.$t$,
    $t$validate_event_vehicle_driver$t$, $t$Uzupełnij datę wydarzenia, aby sprawdzić ważność uprawnień kierowcy.$t$, $t$Uzupełnij datę eventu, aby sprawdzić ważność uprawnień kierowcy.$t$,
    $t$validate_location_rooms$t$, $t$Nie można usunąć sali przypisanej do wydarzenia$t$, $t$Nie można usunąć sali przypisanej do eventu$t$
  ];
begin
  for r in
    select p.oid, p.proname
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'private') and p.prokind = 'f' and p.proname = any(array[
    $t$assign_warehouse_preparer_to_team$t$,
    $t$accept_inquiry_offer$t$,
    $t$accept_seller_offer_review$t$,
    $t$accept_warehouse_event$t$,
    $t$acknowledge_event_arrangements$t$,
    $t$acknowledge_event_equipment_return_issues$t$,
    $t$add_event_partner_commission$t$,
    $t$add_event_settlement_seller$t$,
    $t$add_event_step$t$,
    $t$advance_realization$t$,
    $t$apply_invoice_event_company$t$,
    $t$apply_saved_vehicle_travel_phases$t$,
    $t$appoint_realization_manager$t$,
    $t$approve_event_settlement$t$,
    $t$assign_event_employee_to_phases_with_conflict_decision$t$,
    $t$begin_offer_amendment$t$,
    $t$book_seller_owner_profit_commission$t$,
    $t$can_use_event_invoice_source$t$,
    $t$change_event_contract_template$t$,
    $t$check_assignment_transport_vehicle$t$,
    $t$check_unreturned_vehicles$t$,
    $t$check_vehicle_availability_on_assign$t$,
    $t$complete_seller_event_handoff$t$,
    $t$confirm_event_equipment_loadback$t$,
    $t$confirm_event_equipment_return$t$,
    $t$confirm_seller_offer_realization$t$,
    $t$convert_inquiry_to_event$t$,
    $t$convert_proforma_atomic$t$,
    $t$create_final_invoice_atomic$t$,
    $t$decide_event_equipment_shortages$t$,
    $t$delete_event_settlement_line$t$,
    $t$derive_event_payment_due_date$t$,
    $t$enforce_sales_partner_event_commission$t$,
    $t$ensure_seller_offer_event$t$,
    $t$equipment_check_carry_finish$t$,
    $t$equipment_checklist_lock$t$,
    $t$equipment_confirm_dispatch$t$,
    $t$event_settlement_auto_lines$t$,
    $t$event_settlement_compute$t$,
    $t$event_step_plan$t$,
    $t$event_workflow_readiness_original$t$,
    $t$finance_open_items$t$,
    $t$get_event_arrangements$t$,
    $t$get_event_calculation_equipment$t$,
    $t$get_event_equipment_checklist$t$,
    $t$get_event_financial_summary$t$,
    $t$get_event_onsite_contacts$t$,
    $t$get_event_preflight$t$,
    $t$get_event_preflight_core$t$,
    $t$get_event_required_mavinci_live_modules$t$,
    $t$get_event_responsibility_team$t$,
    $t$get_event_sales_overview$t$,
    $t$get_event_seller_correspondence$t$,
    $t$get_event_settlement$t$,
    $t$get_event_steps$t$,
    $t$get_financial_report$t$,
    $t$get_my_sales_financial_report$t$,
    $t$get_my_seller_cockpit$t$,
    $t$get_or_create_documents_subfolder$t$,
    $t$get_seller_event_draft$t$,
    $t$get_vehicle_timeline$t$,
    $t$guard_automatic_commission$t$,
    $t$guard_inquiry_event_link$t$,
    $t$guard_invoice_party_data_correction$t$,
    $t$guard_pending_seller_event$t$,
    $t$guard_personnel_work$t$,
    $t$guard_sales_invoice_write$t$,
    $t$guard_warehouse_event_status$t$,
    $t$link_event_cost_invoice$t$,
    $t$link_invoice_to_event_settlement$t$,
    $t$link_offer_context$t$,
    $t$list_event_cost_invoice_candidates$t$,
    $t$list_event_seller_candidates$t$,
    $t$lock_event_settlement$t$,
    $t$log_vehicle_assignment_to_event$t$,
    $t$log_vehicle_handover_to_event_audit$t$,
    $t$notify_assignment_response$t$,
    $t$notify_driver_invitation$t$,
    $t$notify_driver_response$t$,
    $t$notify_employee_assignment$t$,
    $t$notify_event_equipment$t$,
    $t$notify_event_operation$t$,
    $t$notify_event_step$t$,
    $t$notify_phase_assignment$t$,
    $t$notify_phase_assignment_response$t$,
    $t$notify_realization_responsibility$t$,
    $t$notify_settlement$t$,
    $t$notify_vehicle_handover_to_event_managers$t$,
    $t$notify_vehicle_pickup_to_event_managers$t$,
    $t$offset_commission_deduction$t$,
    $t$personnel_contract_rules$t$,
    $t$pickup_vehicle$t$,
    $t$prepare_inquiry_realization$t$,
    $t$prepare_vehicle_handover_context$t$,
    $t$prevent_ledger_mutation$t$,
    $t$process_event_operational_alerts$t$,
    $t$protect_commission_settlement_history$t$,
    $t$protect_payout_event_company$t$,
    $t$protect_seller_owner_profit_commission$t$,
    $t$qualified_vehicle_drivers$t$,
    $t$queue_event_for_warehouse$t$,
    $t$record_ad_hoc_vehicle_handover$t$,
    $t$record_assigned_vehicle_handover$t$,
    $t$record_commission_settlement$t$,
    $t$refresh_event_commissions$t$,
    $t$refresh_event_commissions_safe$t$,
    $t$refresh_event_payment_plan$t$,
    $t$remove_event_settlement_seller$t$,
    $t$reopen_event_equipment_stage$t$,
    $t$request_event_equipment_unlock$t$,
    $t$reserve_selected_equipment$t$,
    $t$revoke_realization_manager$t$,
    $t$sales_showcase_offer_request$t$,
    $t$save_event_settlement_group$t$,
    $t$save_event_settlement_line$t$,
    $t$save_flexible_travel_phase$t$,
    $t$save_inquiry_brief$t$,
    $t$seller_owner_profit_context$t$,
    $t$set_event_payment_plan$t$,
    $t$set_event_sales_shares$t$,
    $t$set_event_settlement_seller_rate$t$,
    $t$settle_commission_deduction$t$,
    $t$settlement_sync_steps$t$,
    $t$snapshot_offer_calculation$t$,
    $t$snooze_event_workflow$t$,
    $t$submit_event_settlement$t$,
    $t$sync_billing_commissions_after_contact$t$,
    $t$sync_event_billing_seller_commissions$t$,
    $t$sync_event_steps$t$,
    $t$translate_permission_key$t$,
    $t$update_accepted_offer_items$t$,
    $t$update_event_step$t$,
    $t$validate_event_referring_sales_partner$t$,
    $t$validate_event_rooms$t$,
    $t$validate_event_vehicle_driver$t$,
    $t$validate_location_rooms$t$
    ])
  loop
    def := pg_get_functiondef(r.oid);
    before := def;
    i := 1;
    while i <= array_length(pairs, 1) loop
      if pairs[i] = r.proname then
        def := replace(def, '''' || pairs[i + 1] || '''', '''' || pairs[i + 2] || '''');
      end if;
      i := i + 3;
    end loop;
    if def <> before then
      execute def;
      changed := changed + 1;
    end if;
  end loop;
  raise notice 'Nazewnictwo „event”: zaktualizowano % funkcji.', changed;
end
$mig$;

-- Dane konfiguracyjne i systemowe opisy (dokładne wartości).
update public.event_steps set title = $t$Wyślij podsumowanie eventu$t$ where title = $t$Wyślij podsumowanie wydarzenia$t$;
update public.event_steps set title = $t$Uzupełnij kluczowe dane eventu$t$ where title = $t$Uzupełnij kluczowe dane wydarzenia$t$;
update public.event_steps set title = $t$Potwierdź wpłatę za event$t$ where title = $t$Potwierdź wpłatę za wydarzenie$t$;
update public.event_steps set title = $t$Wystaw fakturę za event$t$ where title = $t$Wystaw fakturę za wydarzenie$t$;
update public.event_steps set title = $t$Zatwierdź podsumowanie eventu$t$ where title = $t$Zatwierdź podsumowanie wydarzenia$t$;
update public.event_steps set details = $t$Krok zamyka się sam po wystawieniu faktury powiązanej z eventem.$t$ where details = $t$Krok zamyka się sam po wystawieniu faktury powiązanej z wydarzeniem.$t$;
update public.event_steps set details = $t$Krok zamyka się sam, gdy faktury eventu są opłacone.$t$ where details = $t$Krok zamyka się sam, gdy faktury wydarzenia są opłacone.$t$;
update public.event_steps set details = $t$Przyjęcie oznacza, że magazyn odpowiada za przygotowanie sprzętu, zamówienia i sprawdzenia stanu tego eventu. Przyjmująca osoba zostaje opiekunem eventu w magazynie.$t$ where details = $t$Przyjęcie oznacza, że magazyn odpowiada za przygotowanie sprzętu, zamówienia i sprawdzenia stanu tego wydarzenia. Przyjmująca osoba zostaje opiekunem wydarzenia w magazynie.$t$;
update public.event_steps set details = $t$Kierownik realizacji prowadzi event na miejscu: odbiera sprzęt, startuje i kończy realizację, oddaje sprzęt do magazynu. Wyznaczasz go w zakładce Zespół — krok zamknie się sam.$t$ where details = $t$Kierownik realizacji prowadzi wydarzenie na miejscu: odbiera sprzęt, startuje i kończy realizację, oddaje sprzęt do magazynu. Wyznaczasz go w zakładce Zespół — krok zamknie się sam.$t$;
update public.event_steps set details = $t$Checklista sprzętu → Załadunek powrotny: kierownik odhacza przy załadunku po evencie, co wraca z wydanego sprzętu, braki opisuje i zatwierdza listę. Krok zamyka się sam.$t$ where details = $t$Checklista sprzętu → Załadunek powrotny: kierownik odhacza przy załadunku po wydarzeniu, co wraca z wydanego sprzętu, braki opisuje i zatwierdza listę. Krok zamyka się sam.$t$;
